// <auto-generated/>

namespace Fanex.CustomerSetting.Module.SearchCopy.Controllers
{
    using System;
    using System.Configuration;
    using System.Linq;
    using System.Threading;
    using System.Web.Mvc;
    using System.Web.SessionState;
    using App_Start;
    using Common;
    using Core.Models;
    using Core.Web;
    using Core.Web.Controllers;
    using Criteria;
    using Logging.Extensions.Web;
    using NAP.Framework.Data;
    using Security.Authenticate;
    using Services;
    using ViewModels;

    [SessionState(SessionStateBehavior.ReadOnly)]
    public class SuperController : BaseController
    {
        private readonly ISearchCopyService _searchCopyService;

        public SuperController()
            : this(null)
        {
        }

        internal SuperController(ISearchCopyService searchCopyService)
        {
            _searchCopyService = searchCopyService ?? new SearchCopyService();
        }

        [AuthenticateAction(AuthenticateAction.AuthenticationType.Read, "SearchAndCopy")]
        public ActionResult Index()
        {
            ViewBag.CurrentUserId = AppSession.AccId;
            ViewBag.CurrentURL = GetCurrentUrl();

            return View("~/Areas/CustomerSetting/Views/SearchCopy/Super/Index.cshtml");
        }

        public ActionResult SearchExistingSuper(string username, string level = "member")
        {
            var permissionService = new PermissionService();
            var permissionResult = permissionService.CheckSpecialSitePermission(AppSession.AccId, username: username);

            if (permissionResult.ErrorCode != 0)
            {
                return Json(permissionResult, JsonRequestBehavior.AllowGet);
            }

            var result = _searchCopyService.SearchExistingUser(username, IsMember(level));

            return Json(
                new CustomerSettingView(result.CustId, username, result.ParentId, result.BreadCrumbs),
                JsonRequestBehavior.AllowGet);
        }

        public ActionResult GetCustomerInfoByUserId(int custid, string level = "member")
        {
            var custInfo = _searchCopyService.GetCustomerInfoByUserId(custid, IsMember(level));

            return Json(custInfo, JsonRequestBehavior.AllowGet);
        }

        public ActionResult GetSites()
        {
            var sites = _searchCopyService.GetSitesExistingSuper(AppSession.AccId);

            return Json(sites, JsonRequestBehavior.AllowGet);
        }

        [AuthenticateAction(AuthenticateAction.AuthenticationType.Host, "SearchAndCopy")]
        public ActionResult CopyExistingSuper(CustomerInsMemberCriteria criteria, string code)
        {
            int creatorId = AppSession.AccId;
            var permissionService = new PermissionService();
            var permissionResult = permissionService.CheckSpecialSitePermission(creatorId, custId: criteria.ExistingCustId);

            if (permissionResult.ErrorCode != 0)
            {
                return Json(permissionResult, JsonRequestBehavior.AllowGet);
            }

            criteria.Creator = creatorId;
            criteria.CreatorName = AppSession.AccUserName;
            criteria.IP = CurrentContext.Instance.Ip4Address;
            criteria.Userpwd = IBCUtils.Encryption.CfsEnCode(Encryptor.Decrypt(criteria.Userpwd, code));
            criteria.FirstName = criteria.FirstName ?? string.Empty;
            criteria.LastName = criteria.LastName ?? string.Empty;
            criteria.Phone = criteria.Phone ?? string.Empty;
            criteria.MobilePhone = criteria.MobilePhone ?? string.Empty;
            criteria.Fax = criteria.Fax ?? string.Empty;

            Result result;
            var isMember = criteria.CustLevel == 1;

            try
            {
                result = isMember
                    ? _searchCopyService.CopyMember(criteria, SystemId, AppSession.CurrentSession.FromSystem)
                    : _searchCopyService.CopySuper(criteria, SystemId, AppSession.CurrentSession.FromSystem);

                result.ErrorMessage = result.IsSuccess
                    ? $"<div class=\"alertboxscc\"><div>{(isMember ? CopyMessageConstant.SuccessMember : CopyMessageConstant.Success)}</div></div>"
                    : $"<div class=\"alertboxerr\"><div>{(result.ErrorMessage == string.Empty ? (isMember ? CopyMessageConstant.FailedMember : CopyMessageConstant.Failed) : result.ErrorMessage)}</div></div>";
                
                return Json(
                    new CommandResult { Code = result.ErrorCode, Message = result.ErrorMessage },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                ExceptionHandler.Handle(ex);

                return Json(
                    new CommandResult
                    {
                        Code = -1,
                        Message = $"<div class=\"alertboxerr\"><div>{(isMember ? CopyMessageConstant.FailedMember : CopyMessageConstant.Failed)}</div></div>"
                    },
                    JsonRequestBehavior.AllowGet);
            }
        }

        [AuthenticateAction(AuthenticateAction.AuthenticationType.Read, "SearchAndCopy")]
        public ActionResult MultipleAccounts(MultipleAccountsViewModel viewModel)
        {
            var isMember = viewModel.ParentId > 0;
            viewModel.Customer = _searchCopyService.GetCustomerInfoByUserId(viewModel.CustId, isMember);

            if (viewModel.Customer.RoleId == 4)
            {
                viewModel.Sites = _searchCopyService
                    .GetSitesExistingSuper(AppSession.AccId)
                    .Select(s => new SelectListItem
                    {
                        Text = s.SiteName,
                        Value = s.SiteName,
                        Selected = s.SiteName == viewModel.Customer.Site
                    });
            }

            return View("~/Areas/CustomerSetting/Views/SearchCopy/Super/MultipleAccounts.cshtml", viewModel);
        }

        [HttpPost]
        [AuthenticateAction(AuthenticateAction.AuthenticationType.Host, "SearchAndCopy")]
        public ActionResult CheckAvailableUsernames(int custId, int parentId, string usernames)
            => Json(_searchCopyService.CheckAvailableUsernames(usernames), JsonRequestBehavior.DenyGet);

        protected override void OnActionExecuting(ActionExecutingContext filterContext)
        {
            ViewBag.RootUrl = $"{Url.Content("~")}{filterContext.RouteData.DataTokens["area"].ToString()}/{ModuleRegistrator.Module}/";

            base.OnActionExecuting(filterContext);
        }

        private static bool IsMember(string level)
            => level.Equals("member", StringComparison.OrdinalIgnoreCase);  

        private string GetCurrentUrl()
        {
            var uri = System.Web.HttpContext.Current.Request.Url;
            var host = $"{uri.Scheme}{Uri.SchemeDelimiter}{uri.Host}{(uri.Port == 80 ? string.Empty : ":")}{uri.Port}";

            var currentURL = ConfigurationManager.AppSettings["CurrentURL"];
            currentURL = string.Format(currentURL, host);

            return currentURL.StartsWith("http") ? currentURL : "http://" + currentURL;
        }
    }
}
